    const double fin_a = abs_bits(s);
    const bool fin_flag = std::numeric_limits<double>::infinity() > fin_a;
    const double fin_r = fin_flag ? s : std::numeric_limits<double>::quiet_NaN();
    r_out = fin_r;
    flag_out = fin_flag;
