        const float comb_th = s1 + s1_next_;
        const float comb_th_bb = comb_th - s1;
        const float comb_th_t0 = comb_th - comb_th_bb;
        const float comb_th_t1 = s1 - comb_th_t0;
        const float comb_th_t2 = s1_next_ - comb_th_bb;
